import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"数据一致性","description":"","frontmatter":{},"headers":[],"relativePath":"database/redis/basic/consistent.md","filePath":"database/redis/basic/consistent.md"}`),a={name:`database/redis/basic/consistent.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="数据一致性" tabindex="-1">数据一致性 <a class="header-anchor" href="#数据一致性" aria-label="Permalink to “数据一致性”">​</a></h1><ul><li>读取缓存步骤一般没有什么问题，但是一旦涉及到数据更新：数据库和缓存更新，就容易出现缓存(Redis)和数据库（MySQL）间的数据一致性问题。</li><li>不管是先写 MySQL 数据库，再删除 Redis 缓存；还是先删除缓存，再写库，都有可能出现数据不一致的情况： <ul><li>如果删除了缓存 Redis，还没有来得及写库 MySQL，另一个线程就来读取，发现缓存为空，则去数据库中读取数据写入缓存，此时缓存中为脏数据。</li><li>如果先写了库，在删除缓存前，写库的线程宕机了，没有删除掉缓存，则也会出现数据不一致情况。</li><li>因为写和读是并发的，没法保证顺序,就会出现缓存和数据库的数据不一致的问题。</li></ul></li></ul><h2 id="方案-读写同步" tabindex="-1">方案：读写同步 <a class="header-anchor" href="#方案-读写同步" aria-label="Permalink to “方案：读写同步”">​</a></h2><ul><li><p>读的时候，先读缓存，缓存没有的话，就读数据库，然后取出数据后放入缓存，同时返回响应。</p></li><li><p>更新的时候，先更新数据库，然后再删除缓存。</p></li><li><p>缺点：</p><ul><li>会产生数据一致性问题</li></ul></li></ul><h2 id="方案-队列-重试机制" tabindex="-1">方案：队列 + 重试机制 <a class="header-anchor" href="#方案-队列-重试机制" aria-label="Permalink to “方案：队列 + 重试机制”">​</a></h2><ul><li>更新数据库数据；</li><li>缓存因为种种问题删除失败</li><li>将需要删除的 key 发送至消息队列</li><li>自己消费消息，获得需要删除的 key</li><li>继续重试删除操作，直到成功</li><li>缺点 <ul><li>对业务线代码造成大量的侵入</li></ul></li></ul><h2 id="方案-异步更新缓存-基于订阅-binlog-的同步机制" tabindex="-1">方案：异步更新缓存(基于订阅 binlog 的同步机制) <a class="header-anchor" href="#方案-异步更新缓存-基于订阅-binlog-的同步机制" aria-label="Permalink to “方案：异步更新缓存(基于订阅 binlog 的同步机制)”">​</a></h2><ul><li>读 Redis：热数据基本都在 Redis</li><li>写 MySQL: 增删改都是操作 MySQL</li><li>更新 Redis 数据：MySQL 的数据操作 <code>binlog</code>，来更新到 Redis</li><li>读取 <code>binlog</code> 后分析 ，利用消息队列,推送更新各台的 <code>redis</code> 缓存数据。</li><li>这样一旦 MySQL 中产生了新的写入、更新、删除等操作，就可以把 <code>binlog</code> 相关的消息推送至 Redis，Redis 再根据 <code>binlog</code> 中的记录，对 Redis 进行更新。</li><li>其实这种机制，很类似 MySQL 的主从备份机制，因为 MySQL 的主备也是通过 <code>binlog</code> 来实现的数据一致性。</li><li>这里可以结合使用 canal(阿里的一款开源框架)，通过该框架可以对 MySQL 的 <code>binlog</code> 进行订阅，而 <code>canal</code> 正是模仿了 mysql 的 slave 数据库的备份请求，使得 Redis 的数据更新达到了相同的效果。</li><li>当然，这里的消息推送工具你也可以采用别的第三方：kafka、rabbitMQ 等来实现推送更新 Redis。</li></ul>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};